				id: settingTextElem
				height: parent.height;
				text: settingText;
				color: "white";
				font.pixelSize: 22;
				Layout.fillWidth: true;
				selectByMouse: true;
				readOnly: true;
			}

			RowLayout {
				Layout.alignment: Qt.AlignRight;
				width: 225;
				implicitWidth: 225;
				height: parent.height;
				Layout.fillWidth: false;

